describe("TaskFlow — Login", () => {
  beforeEach(() => {
    cy.visit('/login');
  });
  it("logs in with valid credentials", () => {
    cy.get('[data-testid="login-email"]').type('demo@taskflow.io');
    cy.get('[data-testid="login-password"]').type('demo1234');
    cy.get('[data-testid="login-submit"]').click();
    cy.get('[data-testid="dashboard-page"]').should("be.visible");
  });
  it("shows error for wrong credentials", () => {
    cy.get('[data-testid="login-email"]').type('wrong@example.com');
    cy.get('[data-testid="login-password"]').type('wrongpass');
    cy.get('[data-testid="login-submit"]').click();
    cy.get('[data-testid="login-error"]').should("be.visible").and("contain.text", "Invalid");
  });
});

