// Generated by Visual Test Builder
// Flow: TaskFlow — Create Task
// Framework: cypress
// baseUrl: http://localhost:5174
// Tags: tasks, crud

describe("TaskFlow — Task Management", () => {
  beforeEach(() => {
    cy.visit('/login');
  });
  describe("Task CRUD", () => {
    it("login before task operations", () => {
      cy.get('[data-testid="login-email"]').type('demo@taskflow.io');
      cy.get('[data-testid="login-password"]').type('demo1234');
      cy.get('[data-testid="login-submit"]').click();
      cy.get('[data-testid="dashboard-page"]').should("be.visible");
    });
    it("navigates to tasks and opens create form", () => {
      cy.get('[data-testid="nav-tasks"]').click();
      cy.get('[data-testid="tasks-page"]').should("be.visible");
      cy.get('[data-testid="create-task-btn"]').click();
      cy.get('[data-testid="task-form-modal"]').should("be.visible");
      cy.get('[data-testid="task-title-input"]').type('Automated test task');
      cy.get('[data-testid="task-form-submit"]').click();
      cy.get('[data-testid="toast"]').should("be.visible");
    });
  });
});

